// Genera un PDF valido sin dependencias externas (no hay nodo htmlToPdf en n8n).
const rows = $input.all().map(i => i.json);
const hoy = new Date().toISOString().slice(0, 10);
const esc = (s) => String(s ?? '').replace(/([()\\])/g, '\\$1');

const lineas = [`Informe diario de usuarios  -  ${hoy}`, ''];
for (const r of rows) {
  lineas.push(`${r.name}  <${r.email}>  activo=${r.active}  ultimo_acceso=${r.last_login || 'nunca'}`);
}
lineas.push('', `Total de usuarios: ${rows.length}`);

const contenido = 'BT /F1 11 Tf 40 780 Td 15 TL\n' +
  lineas.map(l => `(${esc(l)}) Tj T*`).join('\n') + '\nET';

const objetos = [
  '<< /Type /Catalog /Pages 2 0 R >>',
  '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
  '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>',
  `<< /Length ${Buffer.byteLength(contenido, 'latin1')} >>\nstream\n${contenido}\nendstream`,
  '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
];

let pdf = '%PDF-1.4\n';
const offsets = [];
objetos.forEach((o, i) => { offsets.push(Buffer.byteLength(pdf, 'latin1')); pdf += `${i + 1} 0 obj\n${o}\nendobj\n`; });
const inicioXref = Buffer.byteLength(pdf, 'latin1');
pdf += `xref\n0 ${objetos.length + 1}\n0000000000 65535 f \n` +
       offsets.map(o => String(o).padStart(10, '0') + ' 00000 n \n').join('');
pdf += `trailer\n<< /Size ${objetos.length + 1} /Root 1 0 R >>\nstartxref\n${inicioXref}\n%%EOF\n`;

const buf = Buffer.from(pdf, 'latin1');
return [{
  json: { fecha: hoy, usuarios: rows.length, bytes: buf.length },
  binary: { data: { data: buf.toString('base64'), mimeType: 'application/pdf', fileName: `informe_diario_${hoy}.pdf` } }
}];
